"""Mark the reasonable alternative paths of ``AutoGenerated/path_ranking.json``.

The ranking (schema ``path_ranking/1``, written by the selection lane) says
which paths are reasonable. This module copies that onto the graph: option and
path_step edges of each reasonable path other than the selected one get
``attrs.reasonable``, ``attrs.rank`` and ``attrs.delta_chi2``. A missing
ranking sets nothing, so the page renders as before.
"""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict, List, Mapping, Optional, Sequence, Union

RANKING_SCHEMA = "path_ranking/1"
REASONABLE_CLASS = "reasonable"
REASONABLE_LEGEND = {"label": "reasonable alternative (glows)",
                     "color": "#c77dff"}


class RankingInvalid(ValueError):
    """The ranking file is present but does not follow the contract."""


def load_ranking(path: Union[str, Path]) -> Optional[Dict[str, Any]]:
    """The parsed ranking, or None when the file does not exist."""
    p = Path(path)
    if not p.is_file():
        return None
    data = json.loads(p.read_text(encoding="utf-8"))
    if data.get("schema") != RANKING_SCHEMA:
        raise RankingInvalid("%s: schema is %r, expected %r"
                             % (p, data.get("schema"), RANKING_SCHEMA))
    if not isinstance(data.get("rows"), list):
        raise RankingInvalid("%s: rows must be a list" % p)
    return data


def reasonable_rows(ranking: Mapping[str, Any]) -> List[Dict[str, Any]]:
    """Reasonable rows other than the selected path, best rank first."""
    selected = ranking.get("selected")
    rows = [r for r in ranking["rows"]
            if r.get("reasonable") and r.get("path_id") != selected]
    return sorted(rows, key=lambda r: r.get("rank", 0))


def _mark(attrs: Dict[str, Any], row: Mapping[str, Any]) -> None:
    """Record ``row`` on ``attrs`` unless a better-ranked row already did."""
    if attrs.get("reasonable") and attrs.get("rank", 0) <= row.get("rank", 0):
        return
    attrs["reasonable"] = True
    attrs["rank"] = row.get("rank")
    attrs["delta_chi2"] = row.get("delta_chi2")
    attrs["path_id"] = row.get("path_id")


def mark_options(nodes: Sequence[Dict[str, Any]],
                 rows: Sequence[Mapping[str, Any]],
                 option_id) -> None:
    """Flag the option nodes each reasonable row selects (not gold ones)."""
    by_id = {n["id"]: n for n in nodes if n.get("type") == "option"}
    for row in rows:
        for fork, opt in (row.get("selection") or {}).items():
            node = by_id.get(option_id(fork, opt))
            if node is None or node["attrs"].get("on_active_path"):
                continue
            _mark(node["attrs"], row)


def mark_edges(b: Any, rows: Sequence[Mapping[str, Any]],
               order: Sequence[str], theory_node: str, option_id) -> None:
    """Add path_step edges (class ``reasonable``) along each row's path."""
    for row in rows:
        sel = row.get("selection") or {}
        steps = [theory_node] + [option_id(f, sel[f]) for f in order
                                 if f in sel]
        for source, target in zip(steps, steps[1:]):
            b.edge("path_step", source, target, REASONABLE_CLASS, None,
                   {"reasonable": True, "rank": row.get("rank"),
                    "delta_chi2": row.get("delta_chi2")})


def summary(ranking: Mapping[str, Any],
            rows: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    """The block stored on the graph for the inspector and the list."""
    return {"rule": ranking.get("rule"),
            "reasonable_rule": ranking.get("reasonable_rule"),
            "searched": ranking.get("searched"),
            "selected": ranking.get("selected"),
            "paths": [{"path_id": r.get("path_id"), "rank": r.get("rank"),
                       "delta_chi2": r.get("delta_chi2"),
                       "selection": dict(r.get("selection") or {})}
                      for r in rows]}
